n=30
g=[[0]*n for _ in range(n)]
colors=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
starts=[1,8,15,22,29]
for i,r0 in enumerate(starts):
 for j,c0 in enumerate(starts):
  for dr in range(5):
   for dc in range(5):
    r,c=r0+dr,c0+dc
    if r<n and c<n:
     g[r][c]= (colors[i][j] if i<4 and j<4 and 1<=dr<=3 and 1<=dc<=3 else 4)
# Draw color 3 rectangle connecting tile centers at tile rows/cols 0,2; color 8 rectangle tile rows 1,3 cols 1,2.
centers=[3,10,17,24]
for color,ri,rj,ci,cj in [(3,0,2,0,3),(8,1,3,1,2)]:
 # horizontal sides across adjacent tile-gap spans
 for ti in (ri,rj):
  rr=centers[ti]
  for tj in range(ci,cj):
   # separator between tile tj and tj+1; zero columns after tile border and before next tile border
   for cc in range(starts[tj]+5, starts[tj+1]):
    if g[rr][cc]==0: g[rr][cc]=color
 # vertical sides
 for tj in (ci,cj):
  cc=centers[tj]
  for ti in range(ri,rj):
   for rr in range(starts[ti]+5, starts[ti+1]):
    if g[rr][cc]==0: g[rr][cc]=color
print('\n'.join(' '.join(map(str,row)) for row in g))

